"   azureFail('Azure TTS: '+e.message,text,tok,done)});\n}\n/* 2026.10.23-voz · Azure em streaming: o 1º pedaço de PCM já toca; visemas/palavras entram no relógio conforme chegam */\nfunction azureStreamSpeak(text,tok,done,retried,pr){\n const job=pr.job,slow=S.slow;if(job.done||job.chunks.length)job.cached=job.tFirst&&job.tFirst<performance.now()-30;\n const P=pcmPlayer(tok);let iv=0,iw=0;\n const mouth=fin=>{ if(!P.started)return;const t0=P.t0,vis=job.vis,words=job.words;\n   for(;iv<vis.length-(fin?0:1);iv++){const v=vis[iv],n=vis[iv+1];S.visQ.push({v:AZ_MAP[v.id]||'rest',t:t0+v.ms/1000,d:Math.max(.04,n?(n.ms-v.ms)/1000:.1)})}\n   if(!vis.length)for(;iw<words.length-(fin?0:1);iw++){const w=words[iw],n=words[iw+1];let d=w.d>20?w.d/1000:(n?(n.ms-w.ms)/1000*.85:avgW(w.w));d=Math.max(.1,Math.min(1.2,d));scheduleWord(w.w,t0+w.ms/1000,d*.95)}};\n P.onstart=()=>mouth(false);P.onend=()=>done();\n job.onChunk=null;playJob(job,tok,P);const on=job.onChunk;job.onChunk=c=>{on(c);mouth(false)};\n pr.then(({v,key})=>{ if(!HMMS.includes(text))AZPRE.delete(key); job.onChunk=null; if(tok!==speakToken)return;\n   P.end();mouth(true);let how=job.vis.length?'visemas':job.words.length?'tempo por palavra':'heurística';\n   if(how==='heurística'&&P.started){const ws=text.split(/\\s+/).filter(Boolean);const est=estDur(ws);timelineWords(ws,P.t0,Math.max(.5,Math.min(2,P.total/est)))}\n   diag('tts','Azure '+v+' · streaming · '+ttsStat(job)+' · '+azShowNow(v)+' · boca: '+how);\n }).catch(e=>{job.onChunk=null;azResetSyn(); if(tok!==speakToken)return;\n   if(P.started){P.end();diag('err','Azure TTS cortou no meio: '+e.message);return}\n   P.cancel();\n   if(!retried&&isHD(azVoice(slow))&&!/1006|Unable to contact|network/i.test(e.message)){azMarkHdBad(e.message);return azureSpeak(text,tok,done,true)}\n   azureFail('Azure TTS: '+e.message,text,tok,done)});\n}\n/* 2026.10.23-voz · Voz do Grok (xAI TTS, POST /v1/tts): PCM 24 kHz lido em streaming do corpo da resposta (fetch + ReadableStream).\n   Mesma chave xAI do localStorage. Falhou antes do 1º som → Azure (ou navegador) toca a frase. Pré-síntese igual à da Azure. */\nconst XAI_VOICES=[['ara','Ara — calorosa e simpática (padrão)'],['eve','Eve — animada (sotaque britânico)'],['celeste','Celeste — acolhedora, confiante'],['luna','Luna — paciente (educação)'],['iris','Iris — simpática, alto astral'],['ursa','Ursa — amigável, calma'],['lumen','Lumen — clara (educação)'],['aurora','Aurora — serena'],['sal','Sal — equilibrada'],['rex','Rex — masculina, clara'],['leo','Leo — masculina (britânico)']];\nconst XPRE=new Map();\nfunction xaiText(t){return String(t||'').replace(/[<>\\[\\]]/g,' ').replace(/\\s+/g,' ').trim()} // sem tags de fala acidentais\nfunction xaiSynth(text,slow){\n const voice=(CFG.xaiVoice||'ara').toLowerCase(),speed=slow?Math.max(.7,Math.min(1,S.slowR||.75)):1,key=voice+'|'+speed+'|'+text;\n if(XPRE.has(key))return XPRE.get(key);\n const job={chunks:[],onChunk:null,tReq:performance.now(),tFirst:0,done:false,voice,key,bytes:0};\n job.p=(async()=>{\n  const ctl=new AbortController();const to=setTimeout(()=>ctl.abort(),12000);job.abort=()=>ctl.abort();\n  try{const r=await fetch('https://api.x.ai/v1/tts',{method:'POST',signal:ctl.signal,headers:{'Content-Type':'application/json',Authorization:'Bearer '+xaiKey()},\n     body:JSON.stringify({text:xaiText(text),voice_id:voice,language:'en',output_format:{codec:'pcm',sample_rate:PCM_SR},optimize_streaming_latency:1,speed})});\n   if(!r.ok){let t='';try{t=(await r.text()).slice(0,140)}catch(_){}const e=new Error('HTTP '+r.status+(r.status===401||r.status===403?' (chave xAI recusada ou sem permissão de voz)':r.status===429?' (limite)':'')+(t?' '+t:''));e.status=r.status;throw e}\n   const ct=(r.headers.get('content-type')||'').toLowerCase();\n   const add=u=>{if(!u||!u.length)return;if(!job.tFirst)job.tFirst=performance.now();job.bytes+=u.length;job.chunks.push(u);job.onChunk&&job.onChunk(u)};\n   if(/json/.test(ct)){const j=await r.json();const b=atob(j.audio||'');const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);add(u)}\n   else if(r.body&&r.body.getReader){const rd=r.body.getReader();for(;;){const{done,value}=await rd.read();if(done)break;add(value)}}\n   else add(new Uint8Array(await r.arrayBuffer()));\n   if(!job.bytes)throw new Error('áudio vazio');job.done=true;return job}\n  finally{clearTimeout(to)}})();\n XPRE.set(key,job);job.p.catch(e=>{XPRE.delete(key);if(e&&(e.status===401||e.status===403)){XAI_OFF=e.message;diag('err','voz do Grok: '+e.message+' → voltando para a Azure nesta sessão')}});\n if(XPRE.size>40){const k=[...XPRE.keys()].find(k=>!HMMS.some(h=>k.endsWith('|'+h)));if(k)XPRE.delete(k)}\n return job}\nfunction xaiSpeak(text,tok,done){\n const job=xaiSynth(text,S.slow);if(job.done||job.chunks.length)job.cached=true;\n const ws=text.split(/\\s+/).filter(Boolean);\n const P=pcmPlayer(tok);P.onstart=t0=>{timelineWords(ws,t0,S.slow?1.3:1)};P.onend=()=>done();playJob(job,tok,P);\n job.p.then(()=>{ if(!HMMS.includes(text))XPRE.delete(job.key); job.onChunk=null; if(tok!==speakToken)return; P.end();\n   if(P.started){const est=estDur(ws);const t=T();const sc=Math.max(.5,Math.min(2,P.total/est));\n     // reajusta a boca à duração real (agora conhecida), só para o que ainda não foi dito\n     const tmp=S.visQ.filter(v=>v.t<t);S.visQ=[];timelineWords(ws,P.t0,sc);S.visQ=tmp.concat(S.visQ.filter(v=>v.t>=t))}\n   diag('tts','Grok '+job.voice+' · streaming · '+ttsStat(job)+' · '+(P.total).toFixed(1)+' s · boca heurística');\n   const e=document.getElementById('azNow');if(e)e.textContent='🎙 tocando: Grok '+job.voice+' (xAI)';\n }).catch(e=>{job.onChunk=null; if(tok!==speakToken)return;\n   if(P.started){P.end();diag('err','voz do Grok cortou no meio: '+e.message);return}\n   P.cancel();diag('err','voz do Grok falhou ('+String(e.message).slice(0,90)+') → '+(CFG.azKey?'Azure':'voz do navegador'));\n   if(!xaiSpeak.warned){xaiSpeak.warned=1;note('Voz do Grok indisponível ('+String(e.message).slice(0,60)+') — usando '+(CFG.azKey?'a Azure':'a voz do navegador')+'.')}\n   fallbackSpeak(text,tok,done)});\n}\n"
